1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { Button } from "@/presentation/components/ui/button";
3	import {
4		checkConversationUnlock,
5		MIN_GRAMMAR_POINTS,
6		MIN_VOCAB_COUNT,
7	} from "../../domain/conversation/services/ConversationUnlockService";
8	import type {
9		ConversationJudgeResult,
10		ConversationVerdict,
11	} from "../../domain/conversation/types";
12	import type { VocabularyService } from "../../domain/vocabulary/services/VocabularyLessonService";
13	import { useApp } from "../hooks/useApp";
14	import { useMicRecorder } from "../hooks/useMicRecorder";
15	
16	/**
17	 * How each verdict reads. `"unscored"` is deliberately neither of the other
18	 * two: it is the backend admitting it could not judge the turn, so showing
19	 * it as a fail would blame the learner for a system fault, and showing it as
20	 * a pass would be a lie.
21	 */
22	const VERDICT_PRESENTATION: Record<
23		ConversationVerdict,
24		{ label: string; note: string; color: string }
25	> = {
26		pass: {
27			label: "Good answer",
28			note: "That works as a reply.",
29			color: "var(--color-success, #15803d)",
30		},
31		fail: {
32			label: "Not quite",
33			note: "That does not answer the question yet — try again.",
34			color: "var(--color-danger, #b91c1c)",
35		},
36		unscored: {
37			label: "Could not be scored",
38			note: "Something went wrong on the backend, so this turn was not judged. It does not count against you.",
39			color: "var(--color-text-muted, #6b7280)",
40		},
41	};
42	
43	const BACKEND_UNAVAILABLE_MESSAGE =
44		"The conversation backend is not running, so there is nothing to talk to yet. Start it locally and reload this page.";
45	
46	/**
47	 * The learner's known-word snapshot sent with the opening request — never a
48	 * placeholder, and a real empty array (not an omitted field) when nothing is
49	 * learned yet. Extracted so this mapping stays unit-testable independent of
50	 * the unlock gate, which makes the zero-known-words case unreachable through
51	 * a real render once a learner is actually below `MIN_VOCAB_COUNT` (a
52	 * positive count is required to unlock the page in the first place).
53	 */
54	export function knownWordsFor(
55		vocab: Pick<VocabularyService, "getLearnedEntries">,
56	): string[] {
57		return vocab.getLearnedEntries().map((entry) => entry.thai);
58	}
59	
60	interface SessionQuestion {
61		sessionId: string;
62		questionText: string;
63		questionAudioUrl: string;
64	}
65	
66	/** Pass/fail/unscored, kept as three separate counts (never collapsed). */
67	interface Tally {
68		passed: number;
69		failed: number;
70		unscored: number;
71	}
72	
73	const EMPTY_TALLY: Tally = { passed: 0, failed: 0, unscored: 0 };
74	
75	function tallyTotal(tally: Tally): number {
76		return tally.passed + tally.failed + tally.unscored;
77	}
78	
79	function tallyAfter(tally: Tally, verdict: ConversationVerdict): Tally {
80		return {
81			passed: tally.passed + (verdict === "pass" ? 1 : 0),
82			failed: tally.failed + (verdict === "fail" ? 1 : 0),
83			unscored: tally.unscored + (verdict === "unscored" ? 1 : 0),
84		};
85	}
86	
87	/** e.g. "2 passed / 3 asked, 1 unscored" — always names all three components. */
88	function tallySummary(tally: Tally): string {
89		const base = `${tally.passed} passed / ${tallyTotal(tally)} asked`;
90		return tally.unscored > 0 ? `${base}, ${tally.unscored} unscored` : base;
91	}
92	
93	type Phase =
94		| { kind: "loading" }
95		| { kind: "unavailable" }
96		| { kind: "active"; question: SessionQuestion }
97		| { kind: "summary" };
98	
99	/**
100	 * Spoken conversation practice: a multi-turn session against the real
101	 * backend — hear a question, record a reply, see whether it was judged an
102	 * acceptable answer, then automatically move to the next question until the
103	 * bank's matched tier runs out.
104	 *
105	 * There is deliberately no self-rating, no SRS card and no history entry: a
106	 * judge verdict is a different kind of signal from a recall rating, and how
107	 * it should feed the scheduler, if at all, is not this task's call to make
108	 * (see the Architectural Decision in this task's plan document).
109	 */
110	export function ConversationPracticePage() {
111		const { conversationPractice, vocab, lesson } = useApp();
112		const unlock = checkConversationUnlock(
113			vocab.getLearnedCount(),
114			lesson.getGrammarLearnedCount(),
115		);
116		const [phase, setPhase] = useState<Phase>({ kind: "loading" });
117		const [tally, setTally] = useState<Tally>(EMPTY_TALLY);
118		const [judging, setJudging] = useState(false);
119		const [lastJudgement, setLastJudgement] =
120			useState<ConversationJudgeResult | null>(null);
121		const { state, audioBlob, start, stop, reset } = useMicRecorder();
122		const audioRef = useRef<HTMLAudioElement | null>(null);
123		// The currently-live question's blob URL, so the previous one can be
124		// revoked the moment a new one replaces it — a multi-turn session
125		// creates one blob per question, and none of them are otherwise ever
126		// released for the session's lifetime (AC4).
127		const activeAudioUrlRef = useRef<string | null>(null);
128	
129		const setActiveQuestion = useCallback((question: SessionQuestion) => {
130			if (
131				activeAudioUrlRef.current &&
132				activeAudioUrlRef.current !== question.questionAudioUrl
133			) {
134				URL.revokeObjectURL(activeAudioUrlRef.current);
135			}
136			activeAudioUrlRef.current = question.questionAudioUrl;
137			setPhase({ kind: "active", question });
138		}, []);
139	
140		useEffect(
141			() => () => {
142				if (activeAudioUrlRef.current) {
143					URL.revokeObjectURL(activeAudioUrlRef.current);
144					activeAudioUrlRef.current = null;
145				}
146			},
147			[],
148		);
149	
150		// Starts the session once, only for an unlocked learner — the gate is
151		// enforced here too, not only by hiding the Dashboard tile (task 3.2
152		// AC6/AC7): a learner who navigates here directly while below threshold
153		// must never reach the backend at all.
154		useEffect(() => {
155			if (!unlock.unlocked) return;
156			let cancelled = false;
157			conversationPractice.startSession(knownWordsFor(vocab)).then((result) => {
158				if (cancelled) return;
159				if (result.status === "unavailable") {
160					setPhase({ kind: "unavailable" });
161					return;
162				}
163				setActiveQuestion({
164					sessionId: result.sessionId,
165					questionText: result.questionText,
166					questionAudioUrl: result.questionAudioUrl,
167				});
168			});
169			return () => {
170				cancelled = true;
171			};
172		}, [conversationPractice, vocab, unlock.unlocked, setActiveQuestion]);
173	
174		const activeQuestion = phase.kind === "active" ? phase.question : null;
175	
176		// One finished take → judge it, then automatically advance (AC1) —
177		// never a manual "next" step. Keyed on the blob's identity, so a
178		// re-render never re-submits the same recording.
179		useEffect(() => {
180			if (state !== "stopped" || !audioBlob || !activeQuestion) return;
181			const { sessionId, questionText } = activeQuestion;
182			let cancelled = false;
183			setJudging(true);
184			conversationPractice
185				.judgeReply(sessionId, questionText, audioBlob)
186				.then(async (judgement) => {
187					if (cancelled) return;
188					if (judgement.status === "unavailable") {
189						setJudging(false);
190						setPhase({ kind: "unavailable" });
191						return;
192					}
193					setLastJudgement(judgement);
194					setTally((t) => tallyAfter(t, judgement.verdict));
195	
196					const nextResult = await conversationPractice.next(sessionId);
197					if (cancelled) return;
198					setJudging(false);
199					reset();
200					if (nextResult.status === "unavailable") {
201						setPhase({ kind: "unavailable" });
202					} else if (nextResult.status === "exhausted") {
203						setPhase({ kind: "summary" });
204					} else {
205						setActiveQuestion({
206							sessionId,
207							questionText: nextResult.questionText,
208							questionAudioUrl: nextResult.questionAudioUrl,
209						});
210					}
211				});
212			return () => {
213				cancelled = true;
214			};
215		}, [
216			state,
217			audioBlob,
218			activeQuestion,
219			conversationPractice,
220			reset,
221			setActiveQuestion,
222		]);
223	
224		// Same replay convention as SentenceListeningChallenge /
225		// SymbolDictationChallenge: a fresh `Audio` per press, the previous one
226		// stopped first, rejections swallowed (autoplay policy).
227		const playQuestion = useCallback(() => {
228			if (!activeQuestion) return;
229			if (audioRef.current) {
230				audioRef.current.pause();
231				audioRef.current.currentTime = 0;
232			}
233			const audio = new Audio(activeQuestion.questionAudioUrl);
234			audioRef.current = audio;
235			audio.play().catch(() => {});
236		}, [activeQuestion]);
237	
238		useEffect(
239			() => () => {
240				audioRef.current?.pause();
241				audioRef.current = null;
242			},
243			[],
244		);
245	
246		// The actual security/product boundary (task 3.2's Architectural
247		// Decision) — the Dashboard tile hiding the entry point is only a
248		// discoverability affordance on top of this. A learner who types the
249		// URL directly while below threshold sees this, never the live
250		// recording UI, and nothing above has called the backend to get here.
251		if (!unlock.unlocked) {
252			return (
253				<div className="space-y-4 p-4">
254					<h1 className="text-xl font-semibold">Conversation practice</h1>
255					<p role="alert">
256						Conversation practice unlocks once you know at least {MIN_VOCAB_COUNT}{" "}
257						words and {MIN_GRAMMAR_POINTS} grammar points.
258						{unlock.vocabNeeded > 0 &&
259							` ${unlock.vocabNeeded} more word${unlock.vocabNeeded === 1 ? "" : "s"} needed.`}
260						{unlock.grammarNeeded > 0 &&
261							` ${unlock.grammarNeeded} more grammar point${unlock.grammarNeeded === 1 ? "" : "s"} needed.`}
262					</p>
263				</div>
264			);
265		}
266	
267		if (phase.kind === "loading") {
268			return <p className="p-4">Connecting to the conversation backend…</p>;
269		}
270	
271		// No question means nothing to reply to — so no record control at all,
272		// rather than one that would silently do nothing. The tally so far stays
273		// visible: a learner who got through three questions before the backend
274		// dropped should still see it, not nothing (AC3).
275		if (phase.kind === "unavailable") {
276			return (
277				<div className="space-y-4 p-4">
278					<h1 className="text-xl font-semibold">Conversation practice</h1>
279					{tallyTotal(tally) > 0 && (
280						<output>{tallySummary(tally)} so far.</output>
281					)}
282					<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
283				</div>
284			);
285		}
286	
287		if (phase.kind === "summary") {
288			return (
289				<div className="space-y-4 p-4">
290					<h1 className="text-xl font-semibold">Conversation practice</h1>
291					<output>{tallySummary(tally)}.</output>
292				</div>
293			);
294		}
295	
296		const { questionText } = phase.question;
297	
298		return (
299			<div className="space-y-6 p-4">
300				<h1 className="text-xl font-semibold">Conversation practice</h1>
301	
302				{tallyTotal(tally) > 0 && <p>{tallySummary(tally)} so far.</p>}
303	
304				<section className="space-y-3 text-center">
305					<p className="text-3xl" lang="th">
306						{questionText}
307					</p>
308					<button
309						type="button"
310						onClick={playQuestion}
311						aria-label="Play question"
312						className="inline-flex items-center justify-center w-20 h-20 rounded-full text-4xl"
313						style={{
314							background: "var(--color-surface-2)",
315							color: "var(--color-primary)",
316						}}
317					>
318						🔊
319					</button>
320				</section>
321	
322				<section className="space-y-3">
323					{state === "idle" && !judging && (
324						<Button onClick={start}>Record your reply</Button>
325					)}
326					{state === "recording" && (
327						<Button onClick={stop}>Stop recording</Button>
328					)}
329					{state === "denied" && (
330						<p role="alert">
331							Microphone access needed — allow the microphone in your browser,
332							then try recording again.
333						</p>
334					)}
335					{state === "error" && (
336						<p role="alert">
337							Your microphone could not be started. Check that a recording device
338							is connected and try again.
339						</p>
340					)}
341					{judging && <p>Judging your reply…</p>}
342					{!judging && lastJudgement?.status === "ok" && (
343						<div className="space-y-1">
344							<p
345								style={{
346									color: VERDICT_PRESENTATION[lastJudgement.verdict].color,
347								}}
348							>
349								<strong>
350									{VERDICT_PRESENTATION[lastJudgement.verdict].label}
351								</strong>
352							</p>
353							<p>{VERDICT_PRESENTATION[lastJudgement.verdict].note}</p>
354							<p>
355								We heard: <span lang="th">{lastJudgement.transcript}</span>
356							</p>
357							<p>{lastJudgement.feedbackEn}</p>
358						</div>
359					)}
360				</section>
361			</div>
362		);
363	}
364

