40	function conversationGapMessage(
41		learnedVocabCount: number,
42		learnedGrammarCount: number,
43	): string {
44		if (learnedVocabCount < MIN_VOCAB_COUNT) {
45			return `${learnedVocabCount}/${MIN_VOCAB_COUNT} words learned`;
46		}
47		return `${learnedGrammarCount}/${MIN_GRAMMAR_POINTS} grammar points learned`;
