50	export function Dashboard() {
51		const { state, lesson, review, dashboard, vocab } = useApp();
52		const navigate = useNavigate();
53	
54		const conversationUnlock = checkConversationUnlock(
55			vocab.getLearnedCount(),
56			lesson.getGrammarLearnedCount(),
57		);
58	
59		const nextLesson = lesson.getNextScript();
60		const nextVocabLesson =
61			lesson.getVocabUnlockedCount() > 0 ? vocab.getNextLesson() : null;
62		const nextGrammarLesson = lesson.getNextGrammar();
63		const nextSentenceLesson = lesson.getNextSentence();
64		const scriptDueCount = review.getDueCount("script");
65		const vocabDueCount = review.getDueCount("vocab");
66		const grammarDueCount = review.getDueCount("grammar");
67		const sentenceDueCount = review.getDueCount("sentence");
68		const dueCount =
69			scriptDueCount + vocabDueCount + grammarDueCount + sentenceDueCount;
70		const timeUntilNextReview = review.getTimeUntilNextReview();
71		const forecast = review.getForecast();
72		const leechCount = dashboard.getLeechCount();
73		const stages = dashboard.getStageCounts();
74		const achievements = state.achievements ?? [];
75		const reviewButtonCount = [
76			scriptDueCount,
